"""Role-based permission checks migrated from Meridian CRM 4.2."""


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform the action on the record."""
    role_id = user.get("ROLE_ID", "")

    matching_row = next(
        (
            row
            for row in role_rows
            if row.get("role_id", "") == role_id
            and row.get("object", "") == object
            and row.get("action", "") == action
        ),
        None,
    )

    if matching_row is None:
        return False

    if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
        return False

    if role_id == "ADMIN":
        return True

    scope = matching_row.get("scope", "")

    if scope == "ALL":
        return True
    if scope == "TEAM":
        return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
    if scope == "OWN":
        return record.get("OWNER_UID", "") == user.get("USR_ID", "")

    return False
